import { Group, Mesh, PlaneGeometry, BoxGeometry, MeshStandardNodeMaterial, Color } from 'three/webgpu';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [imageUrl]
 * @property {Array<any>} [textContent]
 * @property {Array<{name:string,params:any,trigger:string}>} [cinematicPrimitives]
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {any} textureLoader
 * @property {any} glbLoader
 * @property {any} videoLoader
 * @property {any} fontAtlas
 * @property {Object<string,Function>} primitives
 * @property {Function} emit
 * @property {string} [tier]
 */

/**
 * Create the loop column gallery node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const group = new Group();

  // ---- Colors -------------------------------------------------
  const COLORS = {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
  };

  // ---- Geometry constants ---------------------------------------
  const PLATE_WIDTH = 1.9;
  const PLATE_HEIGHT = 1.2;
  const PLATE_DEPTH = 0.02;
  const BEVEL_THICK = 0.03;
  const PLATE_PITCH = 1.5;
  const COLUMN_X = 0.9;
  const NUM_PLATES = 6;

  // ---- Load texture ---------------------------------------------
  const texturePromise = ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((tex) => {
      // Apply to all plate materials once loaded
      plateMaterials.forEach((mat) => {
        mat.map = tex;
        mat.needsUpdate = true;
      });
    })
    .catch(() => {
      // silently ignore – plates will appear without map
    });

  // ---- Materials ------------------------------------------------
  const plateMaterials = [];
  const frameMaterials = [];

  for (let i = 0; i < NUM_PLATES; i++) {
    const plateMat = new MeshStandardNodeMaterial({
      color: new Color(COLORS.surface),
      roughness: 0.6,
      metalness: 0.1,
      clearcoat: 0.1,
    });
    plateMaterials.push(plateMat);

    const frameMat = new MeshStandardNodeMaterial({
      color: new Color(COLORS.ink),
      roughness: 0.5,
      metalness: 0.5,
      clearcoat: 0,
    });
    frameMaterials.push(frameMat);
  }

  // ---- Create plates & frames -----------------------------------
  const plates = [];

  for (let i = 0; i < NUM_PLATES; i++) {
    const yPos = -i * PLATE_PITCH;

    // Plate
    const plateGeo = new PlaneGeometry(PLATE_WIDTH, PLATE_HEIGHT);
    const plateMesh = new Mesh(plateGeo, plateMaterials[i]);
    plateMesh.position.set(COLUMN_X, yPos, 0);
    plateMesh.rotation.x = -Math.PI / 2; // face forward (+Z)
    group.add(plateMesh);

    // Frame (a thin box slightly larger than the plate)
    const frameGeo = new BoxGeometry(
      PLATE_WIDTH + BEVEL_THICK * 2,
      PLATE_HEIGHT + BEVEL_THICK * 2,
      PLATE_DEPTH
    );
    const frameMesh = new Mesh(frameGeo, frameMaterials[i]);
    frameMesh.position.set(COLUMN_X, yPos, -PLATE_DEPTH / 2);
    group.add(frameMesh);

    plates.push({ mesh: plateMesh, y: yPos, index: i });
  }

  // ---- Accent strip for focused plate (closest to y = 0) -------
  const focusedPlate = plates.reduce((best, cur) => {
    return Math.abs(cur.y) < Math.abs(best.y) ? cur : best;
  }, plates[0]);

  const accentGeo = new BoxGeometry(
    0.03,
    PLATE_HEIGHT,
    PLATE_DEPTH
  );
  const accentMat = new MeshStandardNodeMaterial({
    color: new Color(COLORS.accent),
    emissive: new Color(COLORS.accent),
    emissiveIntensity: 1.4,
    roughness: 0.4,
    metalness: 0.2,
  });
  const accentMesh = new Mesh(accentGeo, accentMat);
  const accentX = COLUMN_X - PLATE_WIDTH / 2 - 0.015; // left edge
  accentMesh.position.set(accentX, focusedPlate.y, 0.001);
  accentMesh.rotation.x = -Math.PI / 2;
  group.add(accentMesh);

  // ---- Text ------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((it) => it.role === 'headline') || items[0];
  if (headlineItem) {
    const headline = ctx.fontAtlas.createText(headlineItem.text, {
      fontSize: headlineItem.typography?.fontSize ?? 68,
      color: COLORS.paper,
      align: 'left',
    });
    headline.position.set(-1.6, 1.9, 0);
    group.add(headline);
  }

  const captionItems = items.filter((it) => it.role === 'caption' || it.typography?.fontSize === 18);
  captionItems.forEach((cap, idx) => {
    const yPos = -idx * PLATE_PITCH;
    const txt = ctx.fontAtlas.createText(cap.text, {
      fontSize: cap.typography?.fontSize ?? 18,
      color: COLORS.paper,
      align: 'left',
    });
    txt.position.set(-1.6, yPos, 0);
    group.add(txt);
  });

  // ---- GSAP timeline for focus scaling (optional) ---------------
  const focusScaleTL = gsap.timeline({ paused: true });
  focusScaleTL.to(
    focusedPlate.mesh.scale,
    {
      x: 1.06,
      y: 1.06,
      z: 1.06,
      duration: 0.35,
      ease: 'cubic-bezier(0.215,0.61,0.355,1)',
    },
    0
  );
  focusScaleTL.play();

  // ---- Apply cinematic primitives --------------------------------
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      if (ctx.primitives[prim.name]) {
        const handle = ctx.primitives[prim.name](group, prim.params);
        primitiveHandles.push(handle);
      }
    }
  }

  // Ensure the declared fly-through primitive is present even if not listed
  if (!primitiveHandles.find((h) => h && h.name === 'fly-through')) {
    if (ctx.primitives['fly-through']) {
      const fly = ctx.primitives['fly-through'](group, { depthUnits: 2.5 });
      primitiveHandles.push(fly);
    }
  }

  // ---- Cleanup ---------------------------------------------------
  group.userData.handlers = {};

  group.userData.cleanup = () => {
    // Dispose geometries & materials
    plates.forEach((p) => {
      p.mesh.geometry.dispose();
      plateMaterials[p.index].dispose();
      // frame
      const frame = p.mesh.parent?.children?.find((c) => c !== p.mesh);
      if (frame) {
        frame.geometry.dispose();
        frameMaterials[p.index].dispose();
      }
    });

    accentGeo.dispose();
    accentMat.dispose();

    // Kill GSAP timeline
    focusScaleTL.kill();

    // Cleanup primitives
    primitiveHandles.forEach((h) => {
      if (h && typeof h.cleanup === 'function') {
        h.cleanup();
      }
    });
  };

  return group;
}
